SELECT COUNT(*) FROM sys_user WHERE 1 = 1
AND (username ILIKE CONCAT('%', #{keyword}, '%') OR display_name ILIKE CONCAT('%', #{keyword}, '%'))
AND status = #{status}

SELECT id, username, display_name AS displayName, status, password_change_required AS passwordChangeRequired, last_login_at AS lastLoginAt, created_at AS createdAt, updated_at AS updatedAt, version FROM sys_user WHERE 1 = 1
AND (username ILIKE CONCAT('%', #{keyword}, '%') OR display_name ILIKE CONCAT('%', #{keyword}, '%'))
AND status = #{status}
ORDER BY created_at DESC, id OFFSET #{offset} LIMIT #{limit}

SELECT COUNT(*) FROM sys_role WHERE 1 = 1
AND (code ILIKE CONCAT('%', #{keyword}, '%') OR name ILIKE CONCAT('%', #{keyword}, '%'))
AND status = #{status}

SELECT id, code, name, status, description, created_at AS createdAt, updated_at AS updatedAt, version FROM sys_role WHERE 1 = 1
AND (code ILIKE CONCAT('%', #{keyword}, '%') OR name ILIKE CONCAT('%', #{keyword}, '%'))
AND status = #{status}
ORDER BY created_at DESC, id OFFSET #{offset} LIMIT #{limit}
